using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models;

namespace sv_5e5ee66dd667453fb6ecfc2a501f3f89.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000); // Simulate network call
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300); // Simulate network call
        return !string.IsNullOrWhiteSpace(email) && email.Contains('@') && email.Contains('.');
    }
}

@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var isCurrent = stepIndex == CurrentStep;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

        <div class="@cssClass" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="@(isCompleted ? 0 : -1)">
            <div class="step-circle">
                @if (isCompleted && !isCurrent)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <span class="step-label">@StepNames[stepIndex]</span>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(isCompleted ? "completed" : "")"></div>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.current {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step-circle {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    background: #e2e8f0;
    color: #64748b;
    transition: background 0.2s, color 0.2s;
}

.step.current .step-circle {
    background: #3b82f6;
    color: white;
}

.step.completed .step-circle {
    background: #22c55e;
    color: white;
}

.checkmark {
    font-size: 1.1rem;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 5rem;
    color: #64748b;
}

.step.current .step-label {
    color: #1e293b;
    font-weight: 600;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e2e8f0;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #22c55e;
}

