.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.current {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step-circle {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    background: #e2e8f0;
    color: #64748b;
    transition: background 0.2s, color 0.2s;
}

.step.current .step-circle {
    background: #3b82f6;
    color: white;
}

.step.completed .step-circle {
    background: #22c55e;
    color: white;
}

.checkmark {
    font-size: 1.1rem;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 5rem;
    color: #64748b;
}

.step.current .step-label {
    color: #1e293b;
    font-weight: 600;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #e2e8f0;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #22c55e;
}

