@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models

<div class="personal-info-step">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
        @if (errors.ContainsKey("FullName"))
        {
            <span class="error">@errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="your.email@example.com" />
        @if (errors.ContainsKey("Email"))
        {
            <span class="error">@errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
        @if (errors.ContainsKey("Phone"))
        {
            <span class="error">@errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="Address" @bind:event="oninput" placeholder="Enter your address" rows="3"></textarea>
        @if (errors.ContainsKey("Address"))
        {
            <span class="error">@errors["Address"]</span>
        }
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> errors = new();
    private bool IsValidating;

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            errors["Phone"] = "Phone number is required.";
        if (string.IsNullOrWhiteSpace(Address))
            errors["Address"] = "Address is required.";

        if (errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                errors["Email"] = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-remove" @onclick="HandleRemove" type="button">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company *</label>
            <input type="text" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="Company name" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="Job title" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")); NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Description" @oninput="e => { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }" placeholder="Describe your responsibilities and achievements" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }

    public record WorkEntryData(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Index, Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync(Index);
    }
}

