@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models
@using static sv_5e5ee66dd667453fb6ecfc2a501f3f89.Components.Pages.Apply.WorkEntryForm

<div class="work-history-step">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <WorkEntryForm Index="i"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(Entries.Count > 1)"
                       OnChanged="HandleEntryChanged"
                       OnRemove="HandleRemove" />
    }

    <button class="btn-secondary" @onclick="AddEntry" type="button">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error">@errorMessage</div>
    }

    <div class="form-actions">
        <button class="btn-outline" @onclick="HandleBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<EntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? errorMessage;

    public class EntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private void HandleRemove(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void HandleEntryChanged(WorkEntryData data)
    {
        if (data.Index < Entries.Count)
        {
            var entry = Entries[data.Index];
            entry.Company = data.Company;
            entry.Title = data.Title;
            entry.StartDate = data.StartDate;
            entry.EndDate = data.EndDate;
            entry.IsCurrent = data.IsCurrent;
            entry.Description = data.Description;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models
@using static sv_5e5ee66dd667453fb6ecfc2a501f3f89.Components.Pages.Apply.ReferenceForm

<div class="references-step">
    <h2>References</h2>
    <p class="subtitle">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var refEntry = References[i];
        <ReferenceForm Index="i"
                       Name="@refEntry.Name"
                       Relationship="@refEntry.Relationship"
                       Email="@refEntry.Email"
                       Phone="@refEntry.Phone"
                       ShowRemove="@(References.Count > 1)"
                       OnChanged="HandleReferenceChanged"
                       OnRemove="HandleRemove" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference" type="button">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error">@errorMessage</div>
    }

    <div class="form-actions">
        <button class="btn-outline" @onclick="HandleBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? errorMessage;

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void HandleRemove(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
        }
    }

    private void HandleReferenceChanged(ReferenceData data)
    {
        if (data.Index < References.Count)
        {
            var refEntry = References[data.Index];
            refEntry.Name = data.Name;
            refEntry.Relationship = data.Relationship;
            refEntry.Email = data.Email;
            refEntry.Phone = data.Phone;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (References.Count < 2)
        {
            errorMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var refEntry in References)
        {
            if (string.IsNullOrWhiteSpace(refEntry.Name) || string.IsNullOrWhiteSpace(refEntry.Relationship)
                || string.IsNullOrWhiteSpace(refEntry.Email) || string.IsNullOrWhiteSpace(refEntry.Phone))
            {
                errorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models

<div class="review-step">
    <h2>Review & Submit</h2>
    <p class="subtitle">Please review your application before submitting.</p>

    <section class="review-section">
        <div class="section-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => EditStep(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => EditStep(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="work-entry-review">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => EditStep(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="reference-review">
                <strong>@reference.Name</strong> &mdash; @reference.Relationship
                <div>@reference.Email | @reference.Phone</div>
            </div>
        }
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => EditStep(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    <div class="form-actions">
        <button class="btn-outline" @onclick="HandleBack" type="button">Back</button>
        <button class="btn-primary btn-submit" @onclick="HandleSubmit" type="button" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task EditStep(int step)
    {
        await OnEditStep.InvokeAsync(step);
    }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

