@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models
@using static sv_5e5ee66dd667453fb6ecfc2a501f3f89.Components.Pages.Apply.ReferenceForm

<div class="references-step">
    <h2>References</h2>
    <p class="subtitle">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var refEntry = References[i];
        <ReferenceForm Index="i"
                       Name="@refEntry.Name"
                       Relationship="@refEntry.Relationship"
                       Email="@refEntry.Email"
                       Phone="@refEntry.Phone"
                       ShowRemove="@(References.Count > 1)"
                       OnChanged="HandleReferenceChanged"
                       OnRemove="HandleRemove" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference" type="button">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error">@errorMessage</div>
    }

    <div class="form-actions">
        <button class="btn-outline" @onclick="HandleBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? errorMessage;

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void HandleRemove(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
        }
    }

    private void HandleReferenceChanged(ReferenceData data)
    {
        if (data.Index < References.Count)
        {
            var refEntry = References[data.Index];
            refEntry.Name = data.Name;
            refEntry.Relationship = data.Relationship;
            refEntry.Email = data.Email;
            refEntry.Phone = data.Phone;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (References.Count < 2)
        {
            errorMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var refEntry in References)
        {
            if (string.IsNullOrWhiteSpace(refEntry.Name) || string.IsNullOrWhiteSpace(refEntry.Relationship)
                || string.IsNullOrWhiteSpace(refEntry.Email) || string.IsNullOrWhiteSpace(refEntry.Phone))
            {
                errorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

