@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models

<div class="review-step">
    <h2>Review & Submit</h2>
    <p class="subtitle">Please review your application before submitting.</p>

    <section class="review-section">
        <div class="section-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => EditStep(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => EditStep(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="work-entry-review">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => EditStep(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="reference-review">
                <strong>@reference.Name</strong> &mdash; @reference.Relationship
                <div>@reference.Email | @reference.Phone</div>
            </div>
        }
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => EditStep(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    <div class="form-actions">
        <button class="btn-outline" @onclick="HandleBack" type="button">Back</button>
        <button class="btn-primary btn-submit" @onclick="HandleSubmit" type="button" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task EditStep(int step)
    {
        await OnEditStep.InvokeAsync(step);
    }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

arguments.file_text:
@page "/apply"
@using sv_5e5ee66dd667453fb6ecfc2a501f3f89.Models
@using static sv_5e5ee66dd667453fb6ecfc2a501f3f89.Components.Pages.Apply.WorkHistoryStep
@using static sv_5e5ee66dd667453fb6ecfc2a501f3f89.Components.Pages.Apply.ReferencesStep
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    @if (isSubmitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@applicationId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@personalFullName"
                                  Email="@personalEmail"
                                  Phone="@personalPhone"
                                  Address="@personalAddress"
                                  ValidateEmail="ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="@GetWorkEntries()"
                            References="@GetReferences()"
                            CoverLetter="@coverLetter"
                            IsSubmitting="@isSubmitting"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="GoBack" />
                break;
        }
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;

    // Personal Info state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Work History state
    private List<EntryModel> workEntries = new() { new EntryModel() };

    // References state
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Cover Letter state
    private string coverLetter = "";

    private async Task<bool> ValidateEmailAsync(string email)
    {
        return await ApplicationService.ValidateEmailAsync(email);
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<EntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        StateHasChanged();

        var application = new JobApplication(
            GetPersonalInfo(),
            new WorkHistory(GetWorkEntries()),
            GetReferences(),
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
        isSubmitted = true;
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
}

.apply-page {
    max-width: 48rem;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 1.5rem;
    color: #1e293b;
}

/* Form elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
